import{_ as d,K as i,a as n,c as o,ac as a,q as r}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"数据结构导论（02142） · 图：存储、遍历与典型应用至练习验收","description":"从线性表、栈队列到树图，再理解查找与排序；包含复杂度、手算与算法入口。","frontmatter":{"title":"数据结构导论（02142） · 图：存储、遍历与典型应用至练习验收","description":"从线性表、栈队列到树图，再理解查找与排序；包含复杂度、手算与算法入口。","splitFrom":"principles/data-structures/foundations/datastructure.md","showdocs":{"topics":[{"id":"data-structures","title":"数据结构","link":"/topics/data-structures/"}],"kind":"专题笔记","scope":"general","audience":"general","group":"原理与设计","seriesTitle":"数据结构导论（02142）","summary":"从线性表、栈队列到树图，再理解查找与排序；包含复杂度、手算与算法入口。","status":"active","related":[{"title":"数据结构导论（02142）","link":"/principles/data-structures/foundations/datastructure","kind":"专题笔记","scope":"general","audience":"general"},{"title":"数据结构导论（02142） · 基本概念与复杂度至树与二叉树","link":"/principles/data-structures/foundations/datastructure-part-01","kind":"专题笔记","scope":"general","audience":"general"},{"title":"并查集","link":"/principles/data-structures/trees/union-find","kind":"系统学习","scope":"general","audience":"general"},{"title":"层序遍历","link":"/principles/data-structures/trees/tree-level-order","kind":"系统学习","scope":"general","audience":"general"},{"title":"差分数组","link":"/principles/data-structures/structures/difference-array","kind":"系统学习","scope":"general","audience":"general"}],"prev":{"text":"数据结构导论（02142） · 基本概念与复杂度至树与二叉树","link":"/principles/data-structures/foundations/datastructure-part-01"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"数据结构导论（02142） · 基本概念与复杂度至树与二叉树","link":"/principles/data-structures/foundations/datastructure-part-01"},"next":false},"headers":[],"relativePath":"principles/data-structures/foundations/datastructure-part-02.md","filePath":"principles/data-structures/foundations/datastructure-part-02.md"}'),s={name:"principles/data-structures/foundations/datastructure-part-02.md"};function l(c,e,p,u,h,g){const t=i("Mermaid");return n(),o("div",null,[e[0]||(e[0]=a('<h1 id="数据结构导论-02142-·-图-存储、遍历与典型应用至练习验收" tabindex="-1">数据结构导论（02142） · 图：存储、遍历与典型应用至练习验收 <a class="header-anchor" href="#数据结构导论-02142-·-图-存储、遍历与典型应用至练习验收" aria-label="Permalink to &quot;数据结构导论（02142） · 图：存储、遍历与典型应用至练习验收&quot;">​</a></h1><p><a href="/principles/data-structures/foundations/datastructure">返回分篇目录</a></p><p>学习顺序是：先分清逻辑结构与存储方式，再学习线性表、栈队列、树和图，最后比较查找与排序。每一类结构都按“表示 → 操作 → 复杂度 → 选择条件”理解，算法实现可继续读对应手册。</p><h2 id="graphs" tabindex="-1">图：存储、遍历与典型应用 <a class="header-anchor" href="#graphs" aria-label="Permalink to &quot;图：存储、遍历与典型应用 {#graphs}&quot;">​</a></h2><h3 id="图与邻接关系" tabindex="-1">图与邻接关系 <a class="header-anchor" href="#图与邻接关系" aria-label="Permalink to &quot;图与邻接关系 {#图与邻接关系}&quot;">​</a></h3><p>图用 <code>G=(V,E)</code> 表示。基础课程常约定 V 非空，E 可空；有向边有起终点，无向边没有方向。是否允许重边和自环需先声明，不能把简单图规则默认为所有图的定义。</p><p>简单无向完全图边数为 <code>n(n−1)/2</code>，简单有向完全图为 <code>n(n−1)</code>。无向图各顶点度数之和为 <code>2|E|</code>；有向图入度和、出度和均为 <code>|E|</code>。</p><p>路径连接一串顶点；简单路径通常不重复顶点；环的起终点相同。无向连通图中任意两点可达，不连通时拆成连通分量；有向图要区分单向可达与强连通。</p><h3 id="邻接矩阵与邻接表" tabindex="-1">邻接矩阵与邻接表 <a class="header-anchor" href="#邻接矩阵与邻接表" aria-label="Permalink to &quot;邻接矩阵与邻接表 {#邻接矩阵与邻接表}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表示</th><th>空间与访问特点</th></tr></thead><tbody><tr><td>邻接矩阵</td><td><code>O(V²)</code> 空间；可直接判断两点是否有边；无向图矩阵对称</td></tr><tr><td>邻接表</td><td><code>O(V+E)</code> 空间；便于枚举邻居；无向边通常保存两个邻接项</td></tr></tbody></table><p>带权图要区分“无边”与权重 0，不能用同一个值模糊表示。十字链表、邻接多重表等是为特定有向/无向操作设计的表示，不是另外的逻辑图类型。</p><h3 id="dfs、bfs-与连通分量" tabindex="-1">DFS、BFS 与连通分量 <a class="header-anchor" href="#dfs、bfs-与连通分量" aria-label="Permalink to &quot;DFS、BFS 与连通分量 {#dfs、bfs-与连通分量}&quot;">​</a></h3><p>在下图无向图中，若从A开始且先访问B，DFS可以是A、B、D、C，BFS可以是A、B、C、D。D与两条分支相连，所以访问标记能防止重复处理。</p>',13)),r(t,{source:"Zmxvd2NoYXJ0IFRECiBBWyJBIl0gLS0tIEJbIkIiXQogQSAtLS0gQ1siQyJdCiBCIC0tLSBEWyJEIl0KIEMgLS0tIEQK"}),e[1]||(e[1]=a('<p>DFS 沿一条路径深入再回溯，常用栈；BFS 按距离层次扩展，常用队列。两者都需要访问标记，防止环造成重复访问；BFS 通常在入队时标记。</p><p>邻居访问顺序不同可得到不同遍历序列；遍历本身没有固定唯一答案。要覆盖不连通图，应从每个尚未访问的顶点启动遍历；使用邻接表时总复杂度通常为 <code>O(V+E)</code>。</p><p>实现对照见 <a href="/principles/algorithms/graphs/algorithms-graphs-general-general#scene-reach-and-connect">DFS、BFS 与连通分量</a>。</p><h3 id="最小生成树与拓扑排序" tabindex="-1">最小生成树与拓扑排序 <a class="header-anchor" href="#最小生成树与拓扑排序" aria-label="Permalink to &quot;最小生成树与拓扑排序 {#最小生成树与拓扑排序}&quot;">​</a></h3><p>生成树覆盖连通无向图的全部顶点且没有环，边数为 <code>V−1</code>。遍历生成树不一定是最小生成树；带权图的最小生成树要求总边权最小。</p><ul><li>Prim 从已有树选择连接外部顶点的合适边；Kruskal 按权处理边，常配并查集避免环。实现和数据结构决定复杂度，不能只按稠密/稀疏一句话选定。</li><li>拓扑排序用于有向无环图。可反复输出入度为零顶点并删除其出边；若最终输出数小于 V，说明存在环。</li><li>最短路径与最小生成树的目标不同，不能把“总边权最小”当成“根到每点都最短”。</li></ul><p>具体实现见 <a href="/principles/algorithms/graphs/algorithms-graphs-general-general#scene-connect-minimum-cost">Prim 与 Kruskal 最小生成树</a>、<a href="/principles/algorithms/graphs/algorithms-graphs-general-general#entry-topological-sort-86a49bb696">拓扑排序</a>。</p><p><span id="第六章查找" aria-hidden="true"></span><span id="_1-基本概念" aria-hidden="true"></span><span id="_2-静态查找表" aria-hidden="true"></span><span id="_3-二叉排序树" aria-hidden="true"></span><span id="_4-散列表" aria-hidden="true"></span><span id="_5-小结-2" aria-hidden="true"></span></p><h2 id="search" tabindex="-1">查找：从顺序扫描到散列 <a class="header-anchor" href="#search" aria-label="Permalink to &quot;查找：从顺序扫描到散列 {#search}&quot;">​</a></h2><h3 id="顺序、折半与分块查找" tabindex="-1">顺序、折半与分块查找 <a class="header-anchor" href="#顺序、折半与分块查找" aria-label="Permalink to &quot;顺序、折半与分块查找 {#顺序、折半与分块查找}&quot;">​</a></h3><p>有序数组[2,5,8,11,14]查11时，先与中间8比较，排除8及其左边；再在右半区比较11。区间每次至少缩小，结束条件必须与闭区间或半开区间约定一致。</p>',11)),r(t,{source:"Zmxvd2NoYXJ0IExSCiBBWyLlgJnpgIkyLDUsOCwxMSwxNCJdIC0tPnwiMTHlpKfkuo44InwgQlsi5YCZ6YCJMTEsMTQiXQogQiAtLT4gQ1si5q+U6L6DMTHvvIzmib7liLAiXQo="}),e[2]||(e[2]=a('<p>顺序查找逐项比较，无需有序但最坏 <code>O(n)</code>。折半查找要求有序且能有效访问中间位置，每步缩小区间，最坏 <code>O(log n)</code>；它不是从末尾逐项扫描。</p><p>分块查找先通过块间有序的索引定位块，再在块内查找。使用前先明确索引维护与块内顺序条件。</p><h3 id="二叉搜索树与散列表" tabindex="-1">二叉搜索树与散列表 <a class="header-anchor" href="#二叉搜索树与散列表" aria-label="Permalink to &quot;二叉搜索树与散列表 {#二叉搜索树与散列表}&quot;">​</a></h3><p>二叉搜索树要求左子树键小于当前键、右子树键大于当前键；重复键策略另行定义。查询沿路径进行，复杂度取决于树高；未经平衡的树可能退化为链，不能保证所有输入都是对数级。</p><p>散列表通过哈希定位候选位置，仍需比较原始键以处理碰撞。常见冲突策略有链地址与开放寻址，负载因子和哈希质量影响性能；平均常数级不是最坏常数级。</p><p>静态查找表重点是查询，动态查找表还需支持插入删除；“静态”不等于只能二分，“动态”也不等于只有某一种树。</p><p><span id="第七章排序-重点" aria-hidden="true"></span><span id="_1-概述" aria-hidden="true"></span><span id="_2-插入排序" aria-hidden="true"></span><span id="_3-交换排序" aria-hidden="true"></span><span id="_4-选择排序" aria-hidden="true"></span><span id="_5-并归排序" aria-hidden="true"></span><span id="_6-小结" aria-hidden="true"></span></p><h2 id="sorting" tabindex="-1">排序：过程、稳定性与选择 <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;排序：过程、稳定性与选择 {#sorting}&quot;">​</a></h2><h3 id="先明确稳定性与内外排序" tabindex="-1">先明确稳定性与内外排序 <a class="header-anchor" href="#先明确稳定性与内外排序" aria-label="Permalink to &quot;先明确稳定性与内外排序 {#先明确稳定性与内外排序}&quot;">​</a></h3><p>稳定排序保持相同键记录原来的相对次序。内排序主要在内存完成；外排序还需考虑数据无法整体装入内存时的 I/O。比较辅助空间时不把输入本身再加一次。</p><table tabindex="0"><thead><tr><th>方法</th><th>平均 / 最坏时间</th><th>常见辅助空间</th><th>稳定性（常见实现）</th></tr></thead><tbody><tr><td>直接插入</td><td><code>O(n²)</code> / <code>O(n²)</code></td><td><code>O(1)</code></td><td>稳定</td></tr><tr><td>冒泡</td><td><code>O(n²)</code> / <code>O(n²)</code></td><td><code>O(1)</code></td><td>稳定</td></tr><tr><td>直接选择</td><td><code>O(n²)</code> / <code>O(n²)</code></td><td><code>O(1)</code></td><td>不稳定</td></tr><tr><td>快速</td><td><code>O(n log n)</code> / <code>O(n²)</code></td><td>平均栈 <code>O(log n)</code>，朴素递归最坏 <code>O(n)</code></td><td>不稳定</td></tr><tr><td>堆</td><td><code>O(n log n)</code> / <code>O(n log n)</code></td><td>原地实现 <code>O(1)</code></td><td>不稳定</td></tr><tr><td>数组归并</td><td><code>O(n log n)</code> / <code>O(n log n)</code></td><td><code>O(n)</code></td><td>稳定</td></tr></tbody></table><h3 id="各方法的操作与不变量" tabindex="-1">各方法的操作与不变量 <a class="header-anchor" href="#各方法的操作与不变量" aria-label="Permalink to &quot;各方法的操作与不变量 {#各方法的操作与不变量}&quot;">​</a></h3><p>归并时两侧已经有序，比较各自当前首项，把较小者写入结果并前进该侧指针。下图将[2,5]与[1,4]合并；若键相等先取左侧，才能延续原有相对次序。</p>',13)),r(t,{source:"Zmxvd2NoYXJ0IExSCiBBWyLlt6YyLDXvvJvlj7MxLDQiXSAtLT4gQlsi5Y+W5Y+zMSJdCiBCIC0tPiBDWyLlj5blt6YyIl0KIEMgLS0+IERbIuWPluWPszQiXQogRCAtLT4gRVsi6L+95Yqg5bemNe+8mjEsMiw0LDUiXQo="}),e[3]||(e[3]=a('<ul><li>直接插入：前缀已有序，把当前项插进正确位置；相等键不跨越，保持稳定。</li><li>冒泡：交换逆序相邻项，一趟后一个极值到位；整趟无交换可提前结束。</li><li>直接选择：从未排序区找最小项，与当前首项交换；非相邻交换可能打乱相等键的次序。</li><li>快速：围绕枢轴分区，再递归处理两边。差的枢轴会导致不平衡递归，退化为平方级，但不是“变成冒泡排序”。</li><li>堆：建堆，再反复将堆顶交换到尾部、缩小堆并下沉调整。</li><li>归并：把有序子序列合并，等值时优先取左侧可保持稳定。</li></ul><p>例如冒泡第一趟处理 <code>21,25,49,25,16,8</code> 后得到 <code>21,25,25,16,8,49</code>。后续只处理尚未就位的区间；手算时同时记录比较、移动与边界，避免只背最终结果。</p><p>完整算法示例见 <a href="/principles/algorithms/sorting/algorithms-sorting-general-general#scene-comparison-sort">比较排序实现</a>。</p><h2 id="practice" tabindex="-1">练习验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习验收 {#practice}&quot;">​</a></h2><ol><li>对同一序列分别用数组与链表插入/删除，说明定位成本与修改成本。</li><li>手算循环队列从满到空的下标，覆盖回绕和只剩一个元素。</li><li>为一棵带空子树的二叉树写四种遍历结果，用图核对顺序。</li><li>为含环且不连通的图执行 DFS/BFS，确认每点恰好访问一次。</li><li>用相等键、已有序、逆序和空输入比较排序；分别说明时间上界、递归栈与稳定性。</li></ol>',5))])}const f=d(s,[["render",l]]);export{m as __pageData,f as default};
